CREATE TABLE "ManagedDocument" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"ownerType" TEXT NOT NULL,"ownerId" TEXT NOT NULL,"documentType" TEXT NOT NULL,"title" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'ACTIVE',"currentVersionNumber" INTEGER NOT NULL DEFAULT 1,"expiresAt" DATE,"retentionUntil" DATE,"archivedAt" TIMESTAMP(3),"deletedAt" TIMESTAMP(3),"createdByUserId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ManagedDocument_pkey" PRIMARY KEY ("id"));
CREATE TABLE "DocumentVersion" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"documentId" TEXT NOT NULL,"versionNumber" INTEGER NOT NULL,"objectKey" TEXT NOT NULL,"fileName" TEXT NOT NULL,"contentType" TEXT NOT NULL,"byteSize" INTEGER NOT NULL,"checksum" TEXT,"createdByUserId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "DocumentVersion_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AppNotification" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"userId" TEXT NOT NULL,"eventType" TEXT NOT NULL,"title" TEXT NOT NULL,"body" TEXT NOT NULL,"actionableUrl" TEXT,"channels" JSONB NOT NULL,"status" TEXT NOT NULL DEFAULT 'PERSISTED',"readAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AppNotification_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Reminder" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"userId" TEXT NOT NULL,"sourceType" TEXT NOT NULL,"sourceId" TEXT NOT NULL,"title" TEXT NOT NULL,"dueAt" TIMESTAMP(3) NOT NULL,"status" TEXT NOT NULL DEFAULT 'PENDING',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Reminder_pkey" PRIMARY KEY ("id"));
CREATE TABLE "WorkflowTask" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"assignedToUserId" TEXT NOT NULL,"sourceType" TEXT NOT NULL,"sourceId" TEXT NOT NULL,"title" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'OPEN',"dueAt" TIMESTAMP(3),"priority" TEXT NOT NULL DEFAULT 'NORMAL',"completedAt" TIMESTAMP(3),"completedByUserId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "WorkflowTask_pkey" PRIMARY KEY ("id"));
CREATE TABLE "WorkflowRule" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"eventType" TEXT NOT NULL,"actions" JSONB NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "WorkflowRule_pkey" PRIMARY KEY ("id"));
